pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != address(0));
        vm.assume(newOwner != address(0));
        vm.assume(newOwner != c.owner());

        // The contract's admin is the deployer (this contract's address from setUp)
        address admin = address(this);

        vm.prank(caller);
        (bool success) = address(c).call(abi.encodeWithSignature("setOwner(address)", newOwner));

        if (caller == admin) {
            assertTrue(c.owner() == newOwner);
        } else {
            assertTrue(c.owner() != newOwner);
        }
    }
}

