pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != address(0)); // avoid zero address issues
        // Try to call setOwner as the admin (default is msg.sender of deployment, which is address(this) in test)
        // Since admin is private, we must call via prank with the original deployer
        vm.prank(address(this)); // admin is msg.sender of deployer, which is this contract
        (bool ok, bytes memory ret) = address(c).call(abi.encodeCall(c.setOwner, (newOwner)));
        if (ok) {
            bool returnValue = abi.decode(ret, (bool));
            assertTrue(returnValue == true, "return value should be true on success");
        }
    }
}

