// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        // Only test non-reverting calls
        vm.assume(caller == address(this)); // admin is the deployer

        // Record owner before call
        address ownerBefore = c.owner();

        // Call setOwner
        bool success;
        bool reverted;
        try this.callSetOwner(c, newOwner) {
            success = true;
        } catch {
            reverted = true;
        }

        // If not reverted, check the rule
        if (!reverted) {
            // The reference guarantees: return true AND owner is updated
            // The mutant returns false (default) AND owner is NOT updated
            assertTrue(success == true && c.owner() == newOwner, "Rule: setOwner must return true and set owner");
        }
    }

    // Helper to call setOwner from a different address context
    function callSetOwner(C _c, address _newOwner) external {
        _c.setOwner(_newOwner);
    }
}

