pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != address(0));
        vm.prank(caller);
        (bool success, bytes memory data) = address(c).call(abi.encodeWithSelector(c.setOwner.selector, newOwner));
        bool returnedBool;
        if (data.length >= 32) {
            returnedBool = abi.decode(data, (bool));
        }
        assertTrue(success == (caller == address(this)) || (returnedBool == (caller == address(this))));
    }
}
